#include <WiFi.h>
#include <esp_now.h>

uint8_t EVERYONE[6] = { 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF };  // broadcast

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  WiFi.mode(WIFI_STA);
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW didn't start");
    return;
  }
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, EVERYONE, 6);
  esp_now_add_peer(&peer);
  Serial.println("Ready!");
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    const char message[] = "buzz";
    esp_now_send(___, (const uint8_t*)message, sizeof(message));
    Serial.println("Sent!");
    delay(300);  // one message per press
  }
}

