#include <WiFi.h>
#include <esp_now.h>

uint8_t EVERYONE[6] = { 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF };
volatile bool gotMessage = false;

// ESP-NOW runs this when a message arrives. Keep it short:
// just remember it, and do the beeping in loop().
void received(const esp_now_recv_info_t* info, const uint8_t* data, int length) {
  gotMessage = true;
}

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  WiFi.mode(WIFI_STA);
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW didn't start");
    return;
  }
  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, EVERYONE, 6);
  esp_now_add_peer(&peer);
  esp_now_register_recv_cb(received);
  Serial.println("Ready!");
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    const char message[] = "buzz";
    esp_now_send(EVERYONE, (const uint8_t*)message, sizeof(message));
    Serial.println("Sent!");
    delay(300);
  }
  if (gotMessage) {
    gotMessage = false;
    Serial.println("Message!");
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 880, 200);
    delay(200);
    digitalWrite(LED_PIN, LOW);
  }
}
